/// <reference path="./sigApi.ApiBase.d.ts" />

declare namespace SigApi {
    interface ApiFunctionBlockManager extends ApiBase {
        /**
         * Executes a FunctionBlock
         * 
         * @param {string} name The name of the function block
         * 
         * @returns {Promise} Promise -> resolve: () => void, reject: (string) => void
         * 
         * A promise that is resolved when the functionblock is done executing
         * 
         * The reject Function is called with an string which describes the error
         */
        executeFunctionBlock(name: string): Promise<void>
    }
}
